CREATE TABLE IF NOT EXISTS bank_transactions (id bigserial primary key, transaction_reference varchar(30) not null unique, idempotency_key varchar(100) not null unique, customer_number varchar(20) not null, source_account_number varchar(30), destination_account_number varchar(30), type varchar(30) not null, status varchar(20) not null, amount numeric(19,2) not null, currency varchar(3) not null, description varchar(255), created_at timestamp not null, updated_at timestamp not null);
